head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.procJob;
scwin.vCurDate;
scwin.checkResult;
scwin.checkDateTPlus2;
scwin.checkDateTMinus2;
scwin.mktHoldyYn;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Item);
        scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
        $c.elw.fn_searchCode(); // 공통코드(콤보)조회
        await scwin.getSrtyCode(); // 보증인코드조회

        const sbmOptions = {
            id : "sbm_dts_LP_SAVE",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_LP_SAVE=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        img_Etnlist.setSelectedTabIndex(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08076.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
