///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 공통코드 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    03685	ISU_AGNT_TP_CD							발행대행기관
    03698	ETN_BZ_ADM_COM_TP_CD			사무관리회사
    02323	TAX_TP_CD									과세유형
    03686	DISTR_TP_CD								분배금형태코드
    01650	DRV_CLSS_LST_SETL_METHD_CD	결제방법
     */
    const arrCid = [ // 발행증권에 관한 사항
        {
            cid: "ISU_AGNT_TP_CD",
            cnm: "cmb_ISU_AGNT_TP_CD"
        }, {
            cid: "ETN_BZ_ADM_COM_TP_CD",
            cnm: "cmb_ETN_BZ_ADM_COM_TP_CD"
        }, {
            cid: "TAX_TP_CD",
            cnm: "cmb_TAX_TP_CD"
        }, {
            cid: "DISTR_TP_CD",
            cnm: "cmb_DISTR_TP_CD"
        }, {
            cid: "DRV_CLSS_LST_SETL_METHD_CD",
            cnm: "cmb_LST_SETL_METHD_CD"
        }, {
            cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
            cnm: "cmb_EARNG_STRUCT_TP_CD"
        }, {
            cid: "ETN_EARY_REDMPT_CYCLE_CD",
            cnm: "cmb_EARY_REDMPT_CYCLE_CD"
        }, {
            cid: "VALU_PRC_CALC_INST_CD",
            cnm: "cmb_VALU_PRC1_CALC_INST_CD"
        }, {
            cid: "VALU_MDL_CD",
            cnm: "cmb_VALU_PRC1_VALU_MDL_CD"
        }, {
            cid: "VOLT_KIND_CD",
            cnm: "cmb_VALU_PRC1_VOLT_KIND_CD"
        }, {
            cid: "VOLT_CURSFC_EXST_CD",
            cnm: "cmb_VALU_PRC1_VOLT_CURSFC_CD"
        }, {
            cid: "DRV_CLSS_DIV_TP_CD",
            cnm: "cmb_VALU_PRC1_DIV_CD"
        }, {
            cid: "VALU_PRC_CALC_INST_CD",
            cnm: "cmb_VALU_PRC2_CALC_INST_CD"
        }, {
            cid: "VALU_MDL_CD",
            cnm: "cmb_VALU_PRC2_VALU_MDL_CD"
        }, {
            cid: "VOLT_KIND_CD",
            cnm: "cmb_VALU_PRC2_VOLT_KIND_CD"
        }, {
            cid: "VOLT_CURSFC_EXST_CD",
            cnm: "cmb_VALU_PRC2_VOLT_CURSFC_CD"
        }, {
            cid: "DRV_CLSS_DIV_TP_CD",
            cnm: "cmb_VALU_PRC2_DIV_CD"
        }
    ];
    let objCod;
    url += "&CD_ID_M='ISU_AGNT_TP_CD','ETN_BZ_ADM_COM_TP_CD','TAX_TP_CD','DISTR_TP_CD','DRV_CLSS_LST_SETL_METHD_CD','LOSS_LMT_ETN_EARNG_STRUCT_CD','ETN_EARY_REDMPT_CYCLE_CD'";
    url += ",'VALU_PRC_CALC_INST_CD','VALU_MDL_CD','VOLT_KIND_CD','VOLT_CURSFC_EXST_CD','DRV_CLSS_DIV_TP_CD','EARY_REDMPT_CYCLE_TP_CD','EARY_REDMPT_COND_REL_CD'";
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name searchLPCode
 * @description LP목록 조회 시 콤보 내용 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchLPCode = async function() {
    let strCbdLP = "' ':"; // 초기값
    const sbmOptions = {
        id : "sbm_dts_LP",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_LP=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    for (k = 1; k <= dts_LP.getRowCount(); k++) {
        strCbdLP = strCbdLP + (strCbdLP === "" ? "" : ",") + dts_LP.getCellData(k, "VALUE") + ":" + dts_LP.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_LP, 'LP_MBR_NO', 'Data', strCbdLP);
};

/**
 * @method
 * @name getEtnBaseInfoReadSync
 * @description Etn 상장원부정보를 가져오는데 사용
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getEtnBaseInfoReadSync = async function() {
    // 상장원부정보 조회
    url += "?SCREN_ID=" + "ULDSTF08076.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readIssueBook&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    url += "&P_KEY=" + txb_SearchIsuCd.getValue();
    const sbmOptions = {
        id : "sbm_dts_Etn_Isu",
        action : "/etn/EtnIssueBook.do",
        ref : "",
        target : "dts_Etn_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 상장원부조기상환정보 조회
    url += "?SCREN_ID=" + "ULDSTF08076.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readIssueBookRedmpt&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    url += "&P_KEY=" + txb_SearchIsuCd.getValue();
    const sbmOptions2 = {
        id : "sbm_dts_Etn_Redmpt_Isu",
        action : "/etn/EtnIssueBook.do",
        ref : "",
        target : "dts_Etn_Redmpt_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // LP목록 조회
    url += "?SCREN_ID=" + "ULDSTF08076.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readLpMbrNoIssueBook&inputMessageId=ETN_ISUBOOK_SEARCH_OUT";
    url += "&P_KEY=" + txb_SearchIsuCd.getValue();
    const sbmOptions3 = {
        id : "sbm_dts_LP",
        action : "/etn/EtnIssueBook.do",
        ref : "",
        target : "dts_LP=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // fn_initLpAndDistrPayGridData("N");

};

/**
 * @method
 * @name checkBizClose
 * @description 시장거래일 여부를 확인하는데 사용
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBizClose = async function(obj) {
    url += "?SCREN_ID=" + "ULDSTF08076.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=checkBizClose&inputMessageId=ETN_ISUBOOK_VALID_INOUT";
    url += "&V_EXP_DD=" + obj.getValue();
    const sbmOptions = {
        id : "sbm_dts_getValDt",
        action : "/etn/EtnIssueBook.do",
        ref : "",
        target : "dts_getValDt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.checkResult = dts_getValDt.getCellData(1, "CALND_DD");
