/**
 * @method
 * @name checkDdTm
 * @description 일자,시간 체크 함수
 * @param {*} gubun gubun
 * @param {Object} obj 컴포넌트
 * @param {String} msg 항목명
 * @param {*} checkCompareDate checkCompareDate
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDdTm = async function(gubun, obj, msg, checkCompareDate) {
    if (obj.text.length !== 8) {
        await $c.win.alert("[" + msg + "일]을 정확히 입력하세요.");
        obj.focus();
        return false;
    }
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (gubun === "currDate") {
        if (scwin.vCurDate >= obj.getValue()) {
            await $c.win.alert("[" + msg + "일]을 현재일 이후로 입력하세요.");
            obj.focus();
            return false;
        }
    } else if (gubun === "ExpDdTMinus2") {
        if (checkCompareDate !== obj.getValue()) {
            await $c.win.alert("[" + msg + "일]은 [만기일(T) 기준 T-2]이어야 함.");
            obj.focus();
            return false;
        }
    } else if (gubun === "ExpDdTPlus2") {
        if (checkCompareDate > obj.getValue()) {
            await $c.win.alert("[" + msg + "일]은 [만기일(T) 기준 T+2]보다 작으면 안됨.");
            obj.focus();
            return false;
        }
    } else {

    }
    return true;
};

/**
 * @method
 * @name checkForm
 * @description 상장원부 Validation 체크 함수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_EXP_DD.getValue() === "") {
        await $c.win.alert("[만기일]을 입력하세요.");
        edt_EXP_DD.focus();
        return false;
    }
    if (!$c.lce.checkDdTm("currDate", edt_EXP_DD, "만기", "")) return false;
    await scwin.checkBizClose(edt_EXP_DD); // 만기일(T) 기준T-2, T+2 조회

    if (txb_DISTR_PAY_BAS_DD_CONTN.getValue() === "") {
        await $c.win.alert("[분배금지급기준일]을 입력하세요.");
        txb_DISTR_PAY_BAS_DD_CONTN.focus();
        return false;
    }
    if (txb_DISTR_PAY_DD_CONTN.getValue() === "") {
        await $c.win.alert("[분배금지급일]을 입력하세요.");
        txb_DISTR_PAY_DD_CONTN.focus();
        return false;
    }

    /* 최종거래일은 만기일(T) 기준 T-2이어야 함(거래일 기준)*/
    if (!$c.lce.checkDdTm("ExpDdTMinus2", edt_LSTTRD_DD, "최종거래", scwin.checkDateTMinus2)) return false;
    if (!$c.lce.checkDdTm("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_STRT_DD, "만기상환가격 결정 시작")) return false;
    if (!$c.lce.checkDdTm("ChkEmpty", edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 종료")) return false;
    if (!$c.stf.compareFromToDate(edt_EXP_REDMPT_PRC_DECSN_STRT_DD, edt_EXP_REDMPT_PRC_DECSN_END_DD, "만기상환가격 결정 시작일", "종료일")) return false;

    /* 만기상환금 지급일은 만기일(T) 기준 T+2 보다 작으면 안됨(거래일 기준)*/
    if (!$c.lce.checkDdTm("ExpDdTPlus2", edt_EXP_REDMPT_AMT_PAY_DD, "만기상환금 지급", scwin.checkDateTPlus2)) return false;
    if (edt_HALFWY_REDMPT_UNIT.getValue() === "") {
        await $c.win.alert("[중도상환단위]을 입력하세요.");
        edt_HALFWY_REDMPT_UNIT.focus();
        return false;
    }
    if (txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.getValue() === "") {
        await $c.win.alert("[중도상환 신청주기]을 입력하세요.");
        txb_HALFWY_REDMPT_APPL_CYCLE_CONTN.focus();
        return false;
    }
    if (txb_HALFWY_REDMPT_PRC_DECSN_CONTN.getValue() === "") {
        await $c.win.alert("[중도상환가격 결정일]을 입력하세요.");
        txb_HALFWY_REDMPT_PRC_DECSN_CONTN.focus();
        return false;
    }
    if (txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.getValue() === "") {
        await $c.win.alert("[중도상환금 지급일]을 입력하세요.");
        txb_HALFWY_REDMPT_AMT_PAY_DD_CONTN.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setGridDataSet
 * @description 제3자 LP 그리드목록  dts_LP_SAVE에 설정
 * @returns {void}
 * @hidden N
 */
scwin.setGridDataSet = function() {
    dts_LP_SAVE.removeAll();
    const vIsuCd = dts_Etn_Isu.getCellData(1, "ISU_CD");
    dts_LP_SAVE.setBroadcast(false);
    for (let i = 1, j = 1; i <= dts_LP.getRowCount(); i++) {
        const vLpMbrNo = dts_LP.getCellData(i, "LP_MBR_NO");
        if (vLpMbrNo !== " " && vLpMbrNo !== "") {
            dts_LP_SAVE.insertRow();
            dts_LP_SAVE.setCellData(j, "ISU_CD", vIsuCd);
            dts_LP_SAVE.setCellData(j, "LP_MBR_NO", vLpMbrNo);
            dts_LP_SAVE.setCellData(j, "LP_CONTRT_DD", ''); // not null -> null
            dts_LP_SAVE.setCellData(j, "LP_STRT_DD", ''); // not null -> null
            j++;
        }
    }
    dts_LP_SAVE.setBroadcast(true, true);
};

/**
 * @method
 * @name update
 * @description update 함수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.cp.isModified(dts_Etn_Isu) && !$c.cp.isModified(dts_LP) && !$c.cp.isModified(dts_Etn_Redmpt_Isu)) {
            $c.lce.fn_alertNoUpdate();
            return;
        }
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            await scwin.trs(TR_JOB_UPDATE);
        }
    }
};
